-- chair-step: inverse of read_lane_v2_b3_23_files_account_tiers — un-enrolls files.account_tiers from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'files' and table_name = 'account_tiers' and is_active);
select iam.apply_rls('files', 'account_tiers', (select token from platform.entity_types where schema_name = 'files' and table_name = 'account_tiers' and is_active), (select rls_variant from platform.entity_types where schema_name = 'files' and table_name = 'account_tiers' and is_active));
